#!/usr/bin/env python3
import argparse
import csv
import json
from pathlib import Path
from typing import Any

DB = Path("risk_register.json")
REQUIRED = {"id", "title", "asset", "owner", "likelihood", "impact", "status", "treatment", "review_date"}
LEVELS = {"low": 1, "medium": 2, "high": 3, "critical": 4}

def load() -> list[dict[str, Any]]:
    if not DB.exists():
        return []
    data = json.loads(DB.read_text(encoding="utf-8"))
    if not isinstance(data, list):
        raise ValueError("Risk register must contain a JSON array")
    return data

def save(rows: list[dict[str, Any]]) -> None:
    DB.write_text(json.dumps(rows, indent=2) + "\n", encoding="utf-8")

def validate(record: dict[str, Any]) -> None:
    missing = REQUIRED - record.keys()
    if missing:
        raise ValueError(f"Missing required fields: {', '.join(sorted(missing))}")
    for field in ("likelihood", "impact"):
        value = str(record[field]).lower()
        if value not in LEVELS:
            raise ValueError(f"{field} must be low, medium, high, or critical")

def priority(record: dict[str, Any]) -> int:
    return LEVELS[str(record["likelihood"]).lower()] * LEVELS[str(record["impact"]).lower()]

def cmd_init(_: argparse.Namespace) -> None:
    if not DB.exists():
        save([])
    print(f"Initialized {DB}")

def cmd_add(args: argparse.Namespace) -> None:
    record = json.loads(Path(args.file).read_text(encoding="utf-8"))
    validate(record)
    rows = load()
    if any(row.get("id") == record["id"] for row in rows):
        raise ValueError(f"Risk ID already exists: {record['id']}")
    rows.append(record)
    save(rows)
    print(f"Added {record['id']}")

def cmd_list(args: argparse.Namespace) -> None:
    rows = load()
    if args.status:
        rows = [r for r in rows if r.get("status") == args.status]
    rows.sort(key=priority, reverse=True)
    for r in rows:
        print(f"{r['id']}: priority={priority(r)} status={r['status']} owner={r['owner']} title={r['title']}")

def cmd_report(_: argparse.Namespace) -> None:
    rows = load()
    with open("risk_report.csv", "w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["id", "title", "asset", "owner", "likelihood", "impact", "priority", "status", "treatment", "review_date"])
        for r in sorted(rows, key=priority, reverse=True):
            writer.writerow([r["id"], r["title"], r["asset"], r["owner"], r["likelihood"], r["impact"], priority(r), r["status"], r["treatment"], r["review_date"]])
    print("Wrote risk_report.csv")

def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Local defensive cyber risk register")
    sub = parser.add_subparsers(dest="command", required=True)
    p = sub.add_parser("init"); p.set_defaults(func=cmd_init)
    p = sub.add_parser("add"); p.add_argument("file"); p.set_defaults(func=cmd_add)
    p = sub.add_parser("list"); p.add_argument("--status"); p.set_defaults(func=cmd_list)
    p = sub.add_parser("report"); p.set_defaults(func=cmd_report)
    return parser

if __name__ == "__main__":
    args = build_parser().parse_args()
    try:
        args.func(args)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        raise SystemExit(f"error: {exc}")
